import{z as s,x as A,o as n,c as d,q as i,j as E,D as e,d as l,s as t,S as o}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"Dictionary Learning 超完备字典","description":"","frontmatter":{"title":"Dictionary Learning 超完备字典","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dictionary-learning-interp.md","filePath":"llm/dictionary-learning-interp.md","lastUpdated":1791063341000}'),p={name:"llm/dictionary-learning-interp.md"};function B(m,a,D,c,h,u){const r=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=i('<h1 id="dictionary-learning-超完备字典" tabindex="-1">Dictionary Learning 超完备字典 <a class="header-anchor" href="#dictionary-learning-超完备字典" aria-label="Permalink to &quot;Dictionary Learning 超完备字典&quot;">​</a></h1><div class="epigraph"><p>自然图像的稀疏编码会自发产生局部、定向、带通的感受野，与初级视皮层简单细胞相似；过完备字典加上稀疏系数，是这条路的数学骨架。</p><footer>—— Olshausen &amp; Field, Emergence of simple-cell receptive field properties by learning a sparse code for natural images, Nature 1996</footer></div><p>字典学习（dictionary learning）要找一组向量——字典 \\(D\\)——让数据近似写成少数几列的线性组合。当列数超过数据维度时，字典是超完备（overcomplete）的：表示不唯一，稀疏性成为选择哪一种表示的正则。Olshausen 与 Field 用它解释 V1；Aharon、Elad 与 Bruckstein 的 K-SVD 把它写成可算的交替优化。机制可解释性把同一骨架搬到冻结网络的激活上：Yun 等人 2021 年在 Transformer 隐状态上做稀疏分解，Cunningham 与 Bricken 把字典特化成 <a href="/llm/sae-sparse-autoencoder">SAE</a>。本篇写超完备这一约束本身意味着什么，以及为什么「可解释特征」在数学上几乎必然是过完备的，若你相信 <a href="/llm/superposition-hypothesis">叠加</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>完备正交基（PCA、正交小波）有唯一系数，却不能同时做到「原子比维度多」和「每次只用几个原子」。自然语言与自然图像都表现出：可能的模式种类远多于观测维度，但单次观测只激活其中很少。若强行用 \\(d\\) 个正交方向去装，就会出现多义基向量——一根轴负担几个不共现的模式。超完备字典接受 \\(F\\gt d\\)，用稀疏性换唯一性：在「所有稀疏解」里挑最稀的一个。</p><p><span class="marginnote">直觉类比：RGB 三基色像完备正交基——任何颜色有唯一配方，但表达力受限。超完备稀疏字典像给你 50 种颜料、规定每幅画最多用 3 种：能表达的东西多得多，配方也不再唯一，「最稀」成了挑选规则。</span></p><p>对解释性，这不是审美偏好。若模型真的把多于 \\(d\\) 个特征塞进 \\(d\\) 维激活，任何完备基都必然把若干特征混在同一坐标上。你要么放弃「一个单元一个意思」，要么离开正交完备，走进过完备。字典学习是后者的标准工具。</p><h3 id="稀疏推断与字典更新是两个循环" tabindex="-1">稀疏推断与字典更新是两个循环 <a class="header-anchor" href="#稀疏推断与字典更新是两个循环" aria-label="Permalink to &quot;稀疏推断与字典更新是两个循环&quot;">​</a></h3><p>给定 \\(D\\)，求稀疏系数 \\(a\\) 是稀疏编码（基追踪、ISTA、OMP）。给定一批 \\(a\\)，更新 \\(D\\) 是字典学习。两步交替，目标常写成</p> \\[\\min_{D,A}\\ \\|X-DA\\|_F^2+\\lambda\\|A\\|_1 \\quad\\text{s.t.}\\ \\ \\|d_i\\|_2=1. \\]<p>列归一是为了堵住「放大原子、缩小系数」的平凡逃逸。K-SVD 在更新某一列时，只动该原子被用到的样本，并做一次秩一逼近。SAE 把稀疏推断改成可微的单次编码器，从而能在十亿级 token 激活上用 SGD 走完。代价是编码器可能达不到真正的 \\(\\ell_0\\) 最优。<span class="marginnote">超完备使得 \\(D\\) 的零空间非平凡：\\(Da=Da&#39;\\) 可以有 \\(a\\neq a&#39;\\)。稀疏正则在等价类里选点。若正则与模型真实的特征先验不一致，学到的字典可以重构得很好，却对齐到相关簇而不是因果特征。重构误差低从来不是语义正确的证明。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>在机制可解释性里，数据矩阵 \\(X\\) 的每一列（或每一行）是某个位点上某个 token 的激活。Yun 等人 2021 年的 <em>Transformer visualization via dictionary learning</em> 把上下文化嵌入写成 Transformer factors 的线性叠加，已经是「残差 = 字典 × 稀疏码」这个等式。后来的 SAE 只是把推断网络化，并加上可解释性与因果验收。</p><p>选择 \\(F\\) 是在分辨率与可训练性之间切。\\(F/d=1\\) 退回完备，叠拆不开；\\(F/d\\) 过大则特征分裂、死原子增多、存储按 \\(F\\cdot d\\) 涨。没有与模型参数量绑定的闭式最优 \\(F\\)；经验上从 \\(4\\times\\) 扫到 \\(100\\times\\) 以上，看帕累托与人工抽查。位点也要选：MLP 激活带特权基，残差流没有；注意力输出又是另一套混合。不同位点的字典不能直接当同一组特征用。</p><p><span class="marginnote">数字感受存储压力：取 \\(d=4096\\)、\\(F/d=4\\)，字典有 \\(16384\\) 个原子，每个原子是 \\(4096\\) 维向量，光字典就要存约 \\(6700\\) 万个数，半精度下约 \\(134\\) MB——这只是「一本字典」的体积，\\(F\\) 再往上乘，账单线性跟着走。</span></p> \\[x \\approx D a,\\qquad \\|a\\|_0 \\ll F,\\qquad F\\gt d \\]<p>这是所有后续「单义特征」工作共享的线性代数，而不是某一篇论文的独家公式。</p><h3 id="与神经科学和压缩感知的对照" tabindex="-1">与神经科学和压缩感知的对照 <a class="header-anchor" href="#与神经科学和压缩感知的对照" aria-label="Permalink to &quot;与神经科学和压缩感知的对照&quot;">​</a></h3><p>Olshausen–Field 的数据是图像斑块，先验是空间局部与定向；语言模型激活的先验是未知的语义稀疏。压缩感知保证：若真实信号在某字典下足够稀，且字典满足 RIP 一类条件，则 \\(\\ell_1\\) 可以恢复。激活空间未必满足 RIP，特征也未必严格稀疏。因此可解释性不能引用压缩感知定理当完备性证明，只能把定理当「为什么值得试 \\(\\ell_1\\)」的动机。K-SVD 在中等规模图像上好用，对 LLM 激活的规模与流式需求不友好，这才轮到 SAE。</p>',19)),(n(),E(o,null,{default:e(()=>[t(r,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%BF%80%E6%B4%BB%20%2F%20%E5%9B%BE%E5%83%8F%E5%9D%97%20X%22%5D%20--%3E%20INF%5B%22%E7%A8%80%E7%96%8F%E6%8E%A8%E6%96%AD%20a%22%5D%0A%20%20D%5B%22%E8%B6%85%E5%AE%8C%E5%A4%87%E5%AD%97%E5%85%B8%20D%22%5D%20--%3E%20INF%0A%20%20INF%20--%3E%20REC%5B%22%E9%87%8D%E6%9E%84%20D%20a%22%5D%0A%20%20REC%20--%3E%20UPD%5B%22%E6%9B%B4%E6%96%B0%20D%22%5D%0A%20%20UPD%20--%3E%20D%0A%20%20INF%20--%3E%20SP%5B%22%E7%A8%80%E7%96%8F%E6%AD%A3%E5%88%99%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><h3 id="单义性是对系数的经验检验" tabindex="-1">单义性是对系数的经验检验 <a class="header-anchor" href="#单义性是对系数的经验检验" aria-label="Permalink to &quot;单义性是对系数的经验检验&quot;">​</a></h3><p>过完备的几何后果是特征可以近正交地挤在一起，夹角由共现结构决定。共现高的模式会被学成相关的原子，甚至被合并；共现低的模式可以靠得很近而不常打架——这就是叠加在字典侧的镜像。单义性（monosemanticity）在此有操作定义：一个原子的最大激活样本应能被同一句话解释。这不是数学定理，是对 \\(a_i\\) 的经验检验。</p><p>线性叠加还承诺干预：把 \\(a_i\\) 夹到大值，等于沿 \\(d_i\\) 走，下游若真用这个方向，行为应朝释义所指的概念偏。若行为乱偏，原子可能只是相关、不是因果。字典学习本身不保证因果，只提供候选方向；因果是另一次实验，见 <a href="/llm/scaling-monosemanticity">Scaling Monosemanticity</a> 的特征转向。</p><p><span class="marginnote">常见误区：把「夹一下原子、输出变了」直接当因果证明。方向可能只是与真特征相关——像拽一根和水管并排的绳子，水流变了不代表绳子在控水，可能两者只是绑在同一根杆上。要加对照（消融邻近方向、换上下文重测）才算合格的干预实验。</span></p>',5)),(n(),E(o,null,{default:e(()=>[t(r,{id:"mermaid-67",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20COMP%5B%22%E5%AE%8C%E5%A4%87%E6%AD%A3%E4%BA%A4%E5%9F%BA%3A%20%E5%8F%AA%E6%9C%89%20d%20%E6%A0%B9%E8%BD%B4%22%5D%0A%20%20%20%20C1%5B%22%E7%89%B9%E5%BE%81%E6%95%B0%E8%A2%AB%E9%92%89%E5%9C%A8%20F%20%3D%20d%22%5D%20--%3E%20C2%5B%22%E8%B6%85%E8%BF%87%20d%20%E7%9A%84%E7%89%B9%E5%BE%81%E5%BF%85%E9%A1%BB%E5%85%B1%E7%94%A8%E5%9D%90%E6%A0%87%22%5D%0A%20%20%20%20C2%20--%3E%20C3%5B%22%E4%B8%80%E6%A0%B9%E8%BD%B4%E6%B7%B7%E5%A4%9A%E4%B8%AA%E6%84%8F%E6%80%9D%3A%20%E5%A4%9A%E4%B9%89%22%5D%0A%20%20end%0A%20%20subgraph%20OVER%5B%22%E8%B6%85%E5%AE%8C%E5%A4%87%E5%AD%97%E5%85%B8%3A%20F%20%3E%20d%22%5D%0A%20%20%20%20O1%5B%22%E5%8E%9F%E5%AD%90%E4%B8%AA%E6%95%B0%E8%B6%85%E8%BF%87%E7%BB%B4%E5%BA%A6%22%5D%20--%3E%20O2%5B%22%E7%A8%80%E7%96%8F%E7%B3%BB%E6%95%B0%E6%AF%8F%E6%AC%A1%E5%8F%AA%E6%8C%91%E5%B0%91%E6%95%B0%E5%8E%9F%E5%AD%90%22%5D%0A%20%20%20%20O2%20--%3E%20O3%5B%22%E4%B8%80%E4%B8%AA%E5%8E%9F%E5%AD%90%E5%AF%B9%E5%BA%94%E4%B8%80%E4%B8%AA%E5%80%99%E9%80%89%E5%8D%95%E4%B9%89%E7%89%B9%E5%BE%81%22%5D%0A%20%20end%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<p><span class="marginnote">「超完备」描述的是原子个数相对维度，不是语义覆盖相对世界。\\(F=10^7\\) 的字典仍可能漏掉模型实际在用的方向，同时充满只对训练激活分布负责的碎片特征。完备性是关于线性张成与稀疏码的，不是关于概念本体论的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>字典学习假设近似线性可加。若关键计算发生在无法用稀疏线性组合逼近的弯曲流形上，再过完备也只是局部切空间的一张网。多层、多位点的字典之间没有免费的对应；要对齐电路，需要转码器或激活修补把一层的原子接到下一层。计算上，\\(D\\) 的存储与每次编码的矩阵乘随 \\(F\\) 线性涨，全面套件的训练费是开放生态出现的原因。</p><p>与 PCA 的取舍：PCA 便宜、唯一、可解释性通常差，因为方差方向不是稀疏特征。与 ICA 的取舍：ICA 假设独立源、通常不超过维度。超完备稀疏编码放松独立性到「可以相关但不同时亮」，更贴近叠加。没有一种分解对所有层都最优；报告时应写字典类、宽度、稀疏度，而不是只写「我们做了特征提取」。</p><p><span class="marginnote">不要把一篇 SAE 论文的「特征」和另一篇 K-SVD 论文的「原子」在未对齐的情况下数个数比较。它们可能分解的是不同位点、不同中心化、不同范数约束。公共语言是 \\(x\\approx Da\\) 与稀疏度，不是特征编号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>超完备字典用多于维度的原子加稀疏系数表示数据，牺牲唯一性、换单义候选。</li><li>若叠加为真，完备正交分解必然多义；过完备是线性代数上的对应物。</li><li>推断与字典更新交替；SAE 用一次可微编码代替迭代稀疏编码以换规模。</li><li>重构好只说明张成合理；语义与因果要靠释义和干预另验。</li><li>Olshausen–Field 提供神经科学先例，Yun 2021 提供 Transformer 先例，现代 mech interp 是同一骨架的规模化。</li><li>出处：Olshausen &amp; Field, <em>Nature</em> 381, 607–609 (1996)；Aharon, Elad &amp; Bruckstein, K-SVD, IEEE TSP 2006；Yun et al., 2021；对照 Elhage et al., 2022。</li></ul>',7))])}const f=s(p,[["render",B]]);export{F as __pageData,f as default};
